def replace_exact(text: str, old: str, new: str, count: int = 1) -> str:
    actual = text.count(old)
    if actual != count:
        raise SystemExit(f"anchor mismatch: expected {count}, found {actual}: {old[:120]!r}")
    return text.replace(old, new, count)


